/*\n  # Add Feature Suggestions to Admin Department\n\n  ## Overview\n  Adds Feature Suggestions module to Admin department so admins can manage user improvement requests.\n\n  ## Changes\n  - Add "Feature Suggestions" module to Admin department\n  - Set appropriate permissions (admin only)\n*/\n\n-- Add Feature Suggestions module to Admin department\nINSERT INTO department_modules (department_id, module_key, display_name, description, icon, sort_order, is_active)\nSELECT \n  d.id,\n  'feature_suggestions',\n  'Feature Suggestions',\n  'Review and manage user improvement requests',\n  'Lightbulb',\n  14,\n  true\nFROM departments d\nWHERE d.name = 'admin'\nON CONFLICT (department_id, module_key) DO UPDATE SET\n  display_name = EXCLUDED.display_name,\n  description = EXCLUDED.description,\n  icon = EXCLUDED.icon,\n  sort_order = EXCLUDED.sort_order

\n\n-- Grant access to admins only\nINSERT INTO module_role_access (module_id, role, has_access)\nSELECT dm.id, 'admin', true\nFROM department_modules dm\nJOIN departments d ON dm.department_id = d.id\nWHERE d.name = 'admin' AND dm.module_key = 'feature_suggestions'\nON CONFLICT (module_id, role) DO UPDATE SET has_access = EXCLUDED.has_access

\n
